// Loop over all items
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];

  // 'data' is the name of your binary property (from your screenshot)
  // We read the file buffer from n8n's internal storage
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');

  // Convert the buffer to a Base64 string and save it to a new JSON field
  item.json.audioBase64 = buffer.toString('base64');
}

return items;

// 1. قراءة بيانات العروض والفروع مباشرة من النود السابقة
const inputData = $input.first()?.json || {};
const offersList = Array.isArray(inputData.offers) ? inputData.offers : [];
const branchesList = Array.isArray(inputData.branches) ? inputData.branches : [];

// 2. قراءة رسالة العميل وضمان تحويلها دائماً إلى String عادي
let rawMsg = null;
try {
  rawMsg = $('Edit Fields1')?.first()?.json?.usermessage;
} catch (e) {}

if (rawMsg == null) {
  try {
    rawMsg = $('Aggregate')?.first()?.json?.message;
  } catch (e) {}
}

if (rawMsg == null) {
  try {
    rawMsg = $('Webhook1')?.first()?.json?.body?.entry?.[0]?.messaging?.[0]?.message?.text;
  } catch (e) {}
}

// تحويل أي مصفوفة (List) إلى String واحد مجمع بنظافة
const body = Array.isArray(rawMsg)
  ? rawMsg.filter(Boolean).map(m => (typeof m === 'object' ? JSON.stringify(m) : String(m))).join(" ").trim()
  : (rawMsg != null ? String(rawMsg).trim() : "");

// 3. تنسيق العروض بشكل عربي واضح ومحدد
let offersText = "لا توجد عروض ترويجية نشطة حالياً.";
if (offersList.length > 0) {
  offersText = offersList.map((o, idx) => {
    const price = o.price_after ? ` بسعر ${o.price_after} ج.م` + (o.price_before ? ` (بدلاً من ${o.price_before} ج.م)` : '') : '';
    const desc = o.description ? ` — ${o.description}` : '';
    return `${idx + 1}. [${o.title}]${price}${desc}`;
  }).join('\n');
}

// 4. تجميع وتنسيق الفروع ومناطق التوصيل
let branchesText = "خدمة التوصيل تغطي جميع الفروع.";
if (branchesList.length > 0) {
  const branchMap = {};
  for (const row of branchesList) {
    if (!row || !row.branch_name) continue;
    const bName = String(row.branch_name);
    if (!branchMap[bName]) {
      branchMap[bName] = {
        name: bName,
        address: row.branch_address || '',
        zones: []
      };
    }
    if (row.zone_name) {
      branchMap[bName].zones.push({
        zone: row.zone_name,
        fee: row.delivery_fee,
        time: row.estimated_delivery_time
      });
    }
  }

  branchesText = Object.values(branchMap).map(b => {
    let zonesStr = "التوصيل متاح لكافة المناطق";
    if (b.zones.length > 0) {
      zonesStr = b.zones.map(z => `${z.zone} (توصيل: ${z.fee} ج.م)`).join('، ');
    }
    return `📍 فرع: ${b.name} (${b.address || 'العنوان متاح لدى الفرع'})\n   مناطق التوصيل: ${zonesStr}`;
  }).join('\n');
}

// 5. إرجاع النتيجة للذكاء الاصطناعي
return [
  {
    json: {
      body: body, // نص String مؤكد 100%
      offers: offersText,
      branches: branchesText,
      raw_offers: offersList,
      raw_branches: branchesList
    }
  }
];

// 1. Read the AI Agent's actual output (.output)
const raw = $input.first()?.json?.output 
         || $input.first()?.json?.text 
         || $input.first()?.json?.content 
         || "";

// Remove any markdown ```json wrapping
const cleaned = String(raw).replace(/```json/gi, "").replace(/```/g, "").trim();

let parsed = {};
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  // If parsing fails, use the raw Agent response directly
  parsed = {
    intent: "normal",
    reply: raw
  };
}

const intent = parsed.intent || "normal";
let order = null;
let complaint = null;

// 2. Fetch raw database branches & offers from Code1
let rawOffers = [];
let rawBranches = [];
try {
  const code1Data = $('Code1').first()?.json;
  rawOffers = code1Data?.raw_offers || [];
  rawBranches = code1Data?.raw_branches || [];
} catch (e) {}

// 3. Strict Rule: Only process and match order if intent is 'order'
if (intent === 'order' && parsed.order_details) {
  const o = parsed.order_details;
  let matchedBranchId = null;
  let matchedOfferId = null;
  let matchedDeliveryFee = 0;

  // Match Branch Name -> branch_id UUID
  const branchName = String(o.branch_name || "").trim().toLowerCase();
  if (branchName) {
    const foundBranch = rawBranches.find(b => b.branch_name && (
      b.branch_name.toLowerCase().includes(branchName) || 
      branchName.includes(b.branch_name.toLowerCase())
    ));
    if (foundBranch) matchedBranchId = foundBranch.branch_id;
  }

  // Match Offer Title -> offer_id UUID
  const offerTitle = String(o.offer_title || "").trim().toLowerCase();
  if (offerTitle) {
    const foundOffer = rawOffers.find(of => of.title && (
      of.title.toLowerCase().includes(offerTitle) || 
      offerTitle.includes(of.title.toLowerCase())
    ));
    if (foundOffer) matchedOfferId = foundOffer.id;
  }

  // Match Delivery Zone -> delivery_fee
  const zoneName = String(o.delivery_zone || "").trim().toLowerCase();
  if (zoneName) {
    const foundZone = rawBranches.find(b => b.zone_name && (
      b.zone_name.toLowerCase().includes(zoneName) || 
      zoneName.includes(b.zone_name.toLowerCase())
    ));
    if (foundZone) {
      matchedDeliveryFee = Number(foundZone.delivery_fee) || 0;
      if (!matchedBranchId) matchedBranchId = foundZone.branch_id;
    }
  }

  order = {
    branch_name: o.branch_name || "",
    branch_id: matchedBranchId,
    offer_title: o.offer_title || "",
    offer_id: matchedOfferId,
    delivery_zone: o.delivery_zone || "",
    delivery_fee: matchedDeliveryFee,
    items: o.items || [],
    total_amount: Number(o.total_amount) || 0,
    customer_name: o.customer_name || "",
    phone: o.phone || "",
    address: o.address || "",
    notes: o.notes || ""
  };
}

// 4. Strict Rule: Only process complaint if intent is 'complaint'
if (intent === 'complaint' && parsed.complaint_details) {
  complaint = {
    phone: parsed.complaint_details.phone || "",
    issue: parsed.complaint_details.issue || ""
  };
}

// 5. Read context and contact IDs
let psid = "";
let page_id = "";
let token = "";
let contact_id = "";

try {
  const context = $('Parse Messenger Event').first()?.json;
  psid = context?.psid || "";
  page_id = context?.page_id || "";
  token = context?.token || "";
} catch (e) {}

try {
  contact_id = $('Edit Fields4').first()?.json?.contact_uuid 
            || $('Edit Fields1').first()?.json?.contact_uuid 
            || "";
} catch (e) {}

return [{
  json: {
    intent: intent,
    reply: parsed.reply || raw, // Always uses the AI Agent's actual response
    order_details: order,
    complaint_details: complaint,
    psid: psid,
    page_id: page_id,
    token: token,
    contact_id: contact_id
  }
}];

// 1. Get the new order ID created by Supabase
const orderId = $input.first().json.id;

// 2. Get the items array from the AI Agent
const items = $('Code in JavaScript3').first().json.order_details?.items || [];

// Fallback if no specific items were listed
if (items.length === 0) {
  return [{
    json: {
      order_id: orderId,
      item_name: "طلب وجبات متنوعة",
      quantity: 1,
      notes: ""
    }
  }];
}

// 3. Convert each meal into a separate row for Supabase
return items.map(item => ({
  json: {
    order_id: orderId,
    item_name: item.name || "وجبة",
    quantity: Number(item.qty) || 1,
    notes: item.notes || ""
  }
}));

